  'data.brood-chamber': 'Cámara de cría',
  'swarm.brood.desc': 'Órgano de cría vivo de la Madre del Enjambre. Cada 3 horas de juego genera un Desembarcador por 20 de biomasa, 8 de metal y 2 de microelectrónica por transporte. El crecimiento se detiene en combate, por falta de recursos o con la bodega llena.',
  'data.swarm-leviathan': 'Leviatán',
  'data.leviathan': 'Leviatán',
  'data.leviathan-brood': 'Camada de Leviatán',
  'swarm.leviathan-brood.desc': 'Matriz de cría viva del Leviatán. Cada 3 horas de juego gesta 6 Desembarcadores por 20 de biomasa, 8 de metal y 2 de microelectrónica cada uno. El crecimiento se detiene en combate, por falta de recursos o con la bodega llena.',
  'data.hive-call': 'Llamada de la colmena',
  'data.devour-world': 'Devorar mundo',
  'data.swarm-instinct': 'Instinto de enjambre',
  'swarm.intel.economy': 'El Enjambre consume materia orgánica para tejidos, metal para exoesqueletos y blindajes, y microelectrónica para vías neuronales conductoras. Los mundos industriales alimentan su expansión: la biomasa por sí sola no basta.',
  'swarm.intel.brood': 'La Madre del Enjambre porta una cámara de cría, órgano que gesta Desembarcadores terrestres. Consume biomasa, metal y microelectrónica; las criaturas ocupan espacio de desembarco y asaltan mundos con un asalto convencional. La sola presencia de la Madre no infecta el mundo.',
  'swarm.intel.updated': 'Nuevos datos',
  'swarm.intel.tab': 'Expediente',
  'swarm.intel.title': 'Archivos del Enjambre',
  'swarm.intel.lore': 'Al observar al Enjambre en cada contacto conocemos su composición y cambios. Solo se recogen aquí las formaciones avistadas, no todo su ejército.',
  'swarm.intel.empty': 'Sin formaciones identificadas. Una marca en el radar no revela la composición de la flota.',
