  'pve.pirates.title': 'Primera batalla · Piratas',
  'pve.pirates.approach': 'Cerca hay una base pirata con dos fragatas. Elige la flota inicial, pulsa «Rumbo» y señala la base. Tus fuerzas bastan para ganar este choque. Es un objetivo opcional: las oleadas del Enjambre avanzan sin pausa.',
  'pve.pirates.travel': 'La flota avanza hacia la base. Al topar con los piratas el combate empezará solo. Espera a llegar; el control de velocidad del tiempo está abajo.',
  'pve.pirates.battle': 'La batalla ha comenzado. Abre su ventana: verás fuerzas de ambos bandos, aguante y la cuenta atrás para la siguiente ronda. El daño se resuelve por rondas. La retirada se ordena en la ficha de flota.',
  'pve.pirates.occupy': 'La flota pirata ha sido dispersada, pero la base sigue siendo suya. Tu flota inicial lleva tropas de desembarco: pasa a órbita baja y pulsa «Asalto» para capturar la base desierta.',
  'pve.pirates.won': 'Base tomada, primera batalla concluida. Evalúa las bajas y prepara defensas contra el Enjambre. La victoria en la expedición aún está por llegar.',
  'pve.pirates.cleared': 'El objetivo pirata ya ha sido eliminado. Continúa preparándote para repeler las oleadas del Enjambre.',
  'pve.pirates.recover': 'Ahora mismo no tienes flota de combate. Reconstruye fuerzas en el astillero natal o deja los piratas para más tarde. La expedición sigue.',
  'pve.pirates.show': 'Mostrar base',
  'pve.pirates.open-battle': 'Abrir combate',
  'run.abandon.lost.title': 'Flota perdida',
  'run.abandon.lost.text': 'No queda ninguna nave. Reconstruye la flota en el astillero o finaliza la expedición: recibirás recompensas por oleadas, tareas y bajas como en una derrota.',
  'run.abandon.ask.title': '¿Finalizar expedición?',
