  'tech.node.ace-programs.desc': 'Programas de ases: tripulaciones de élite. +6% daño de lanzaderas, +6% velocidad de flota. Capstone del Comodoro.',
  'tech.node.ai-stewardship.desc': 'Automatización del mando: cede el puesto a una IA de confianza mientras estás desconectado; mantendrá la defensa y devolverá el control a tiempo. Requiere al Supervisor (día 16).',
  'tech.node.combined-arms.desc': 'Armas combinadas: infantería y blindados al unísono. +5% daño en combate terrestre.',
  'tech.node.deep-survey.desc': 'Redes de sensores profundos: +15% alcance de radar.',
  'tech.node.flight-decks.desc': 'Cubiertas de vuelo: ciclo rápido de salidas. +6% velocidad de flota.',
  'tech.node.fortified-infrastructure.desc': 'Doctrina de mundos fortificados: fortalezas de la frontera.',
  'tech.node.garrison-networks.desc': 'Redes de guarnición: la retaguardia se abastece sola. +5% producción.',
  'tech.node.guidance-arrays.desc': 'Matrices de guiado: telemetría de largo alcance. +10% alcance de radar.',
  'tech.node.industrial-automation.desc': 'Mejora logística planetaria: +10% producción.',
  'tech.node.logistics-command.desc': 'Mando logístico: convoyes según lo previsto. +5% producción y +5% velocidad de flota.',
  'tech.node.microelectronics-fabrication.desc': 'Fundiciones orbitales: +5% producción.',
  'tech.node.void-shipworks.desc': 'Cubierta de atraque, cisternas de combustible y andamios integrados en la fortaleza. Desbloquea su propio hangar: las lanzaderas ya no precisan puerto terrestre.',
  'tech.node.void-shielding.desc': 'Emisores de campo por el casco de la fortaleza: el proyectil se absorbe antes de tocar blindaje. Desbloquea el circuito de escudos: 3 niveles, cada uno mayor y de recarga más veloz.',
  'tech.node.void-fortification.desc': 'Nodo de apoyo fuera de sistemas planetarios: estructura portante, cinturón de reactores y dársenas para desarrollar el vacío capturado. Desbloquea la fortaleza del vacío.',
  'tech.node.orbital-defense-grid.desc': 'Red defensiva orbital: desbloquea el emplazamiento de DAA orbital, una batería que dispara a flotas en órbita.',
  'tech.node.orbital-logistics.desc': 'Transporte estandarizado: +12% velocidad de flota.',
  'tech.node.planetary-bastions.desc': 'Bastiones planetarios: industria de defensa de ciclo completo. +8% daño en combate terrestre. Capstone del Mariscal.',
  'tech.node.saturation-barrage.desc': 'Andanada de saturación: satura cualquier defensa antimisiles. +10% daño de misiles. Capstone del Artillero.',
  'tech.node.siege-doctrine.desc': 'Dotaciones de asedio a larga distancia: +8% daño en el espacio.',
  'tech.node.signal-corps.desc': 'Cuerpo de señales: visión unificada del campo de batalla. +8% alcance de radar.',
  'tech.node.strike-vectors.desc': 'Vectores de ataque: trayectorias calculadas de lanzaderas. +8% daño de lanzaderas.',
  'tech.node.void-armadas.desc': 'Doctrina de grandes formaciones: +6% daño en el espacio, +6% velocidad de flota. Requiere 5 sectores propios.',
  'tech.node.warhead-miniaturization.desc': 'Miniaturización de ojivas: andanada más densa por tonelada. +6% daño de misiles.',
